نقش سازمانی: مدیر کارخانه و فرآوری (processing_manager)

درخواست کاربر:
بازیابی -6 واحد افت کرده. ریشه را پیدا کن. (مدیر کارخانه — کارخانهٔ فرآوری مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "plant_performance",
      "description": "عملکرد کارخانه: خوراک، کنسانتره، بازیابی",
      "dimensions": [
        "month",
        "line"
      ],
      "measures": [
        "feed_tons",
        "concentrate_tons",
        "recovery_pct"
      ]
    },
    {
      "dataset": "quality_lab",
      "description": "کیفیت کنسانتره: عیار، عناصر مزاحم",
      "dimensions": [
        "month"
      ],
      "measures": [
        "grade_pct",
        "sulfur_pct",
        "moisture_pct"
      ]
    },
    {
      "dataset": "reagent_usage",
      "description": "مصرف معرف‌ها و مواد شیمیایی",
      "dimensions": [
        "reagent",
        "month"
      ],
      "measures": [
        "kg",
        "cost_per_kg"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "recovery",
      "description": "نرخ بازیابی",
      "formula": "فلز بازیابی‌شده / فلز خوراک",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "reagent_per_ton",
      "description": "مصرف معرف به‌ازای تن",
      "formula": "کیلوگرم معرف / تن خوراک",
      "unit": "کیلوگرم بر تن",
      "dimensions": [
        "reagent"
      ]
    }
  ],
  "business_context": [
    "کارخانهٔ فرآوری مس با ظرفیت اسمی ۱۵۰ تن در ساعت",
    "شش خط فرآوری (خاموت، فلوتاسیون، مغناطیسی)",
    "مصرف انرژی و معرف‌ها بزرگ‌ترین اجزای هزینهٔ عملیاتی کارخانه هستند"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "recovery"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ]
  }
}

TOOL_OBSERVATION:
{
  "recovery": {
    "prev": 84,
    "curr": 78
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "quality_lab",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "feed_grade": 0.64,
  "feed_sulfur": 4.7
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "reagent_usage",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "note": "مصرف معرف ثابت مانده ولی گوگرد خوراک ۴۰٪ افزایش یافته"
}

نقش سازمانی: مدیر کارخانه و فرآوری (processing_manager)

درخواست کاربر:
مصرف انرژی کارخانه یک‌ماه جهش کرد و برگشت. چه رخدادی بود؟ (مدیر کارخانه — کارخانهٔ فرآوری مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "energy_plant",
      "description": "مصرف انرژی کارخانه به تفکیک بخش",
      "dimensions": [
        "section",
        "month"
      ],
      "measures": [
        "kwh",
        "kwh_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "energy_per_ton",
      "description": "مصرف انرژی به‌ازای تن",
      "formula": "کیلووات‌ساعت / تن خوراک",
      "unit": "کیلووات‌ساعت بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "کارخانهٔ فرآوری مس با ظرفیت اسمی ۱۵۰ تن در ساعت",
    "شش خط فرآوری (خاموت، فلوتاسیون، مغناطیسی)",
    "مصرف انرژی و معرف‌ها بزرگ‌ترین اجزای هزینهٔ عملیاتی کارخانه هستند"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "energy_per_ton",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "energy_plant",
    "filters": {
      "period": "month_4"
    }
  }
}

TOOL_OBSERVATION:
{
  "spike_reason": "توقف ۱۲ ساعتهٔ آسیاب اولیه + راه‌اندازی مجدد با مصرف بالا"
}

